7	import { tokenLimit } from '@google/gemini-cli-core';
8	
9	export function getContextUsagePercentage(
10	  promptTokenCount: number,
11	  model: string | undefined,
12	): number {
13	  if (!model || typeof model !== 'string' || model.length === 0) {
14	    return 0;
15	  }
16	  const limit = tokenLimit(model);
17	  if (limit <= 0) {
18	    return 0;
19	  }
20	  return promptTokenCount / limit;
21	}
22	
23	export function isContextUsageHigh(
24	  promptTokenCount: number,
25	  model: string | undefined,
26	  threshold = 0.6,
27	): boolean {
28	  return getContextUsagePercentage(promptTokenCount, model) > threshold;
29	}
